// WF-02: validate + normalize lead info. Returns a structured result
// (does NOT throw) so callers can branch instead of failing.
const items = $input.all();
const DIGITS = (s) => String(s || '').replace(/[^0-9]/g, '');

return items.map((item) => {
  const j = item.json;
  const raw = String(j.mobile || j.phone || '').replace(/[^\d+]/g, '');
  const d = DIGITS(raw);

  let phone = raw;
  if (/^91[6-9]\d{9}$/.test(d)) phone = '+91' + d.slice(2);
  else if (/^0[6-9]\d{9}$/.test(d)) phone = '+91' + d.slice(1);
  else if (/^[6-9]\d{9}$/.test(d)) phone = '+91' + d;

  const email = String(j.email || '').trim().toLowerCase();
  const errors = [];
  if (!String(j.name || '').trim()) errors.push('name_required');
  if (!/^[6-9]\d{9}$/.test(DIGITS(phone))) errors.push('invalid_phone');
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('invalid_email');

  return {
    json: {
      ...j,
      normalized: { phone, phone_raw: raw, email },
      valid: errors.length === 0,
      errors,
    },
  };
});
